line2_camera_archive=Path.cwd()/'CAMERA3_b3ab3d3be1e24ee9b69cf676f3ec4326.zip'
assert not line2_camera_archive.exists(), "Camera package exists; stop, do not retry"
line2_camera_archive.write_bytes(base64.b64decode('',validate=True))
assert hashlib.sha256(line2_camera_archive.read_bytes()).hexdigest()=='202d57b73fddcad201b2917ea87795de5393568462d6737387e28a3a0290157e', "Camera ZIP SHA mismatch"
line2_camera_root=Path.cwd()/'CAMERA3_b3ab3d3be1e24ee9b69cf676f3ec4326'
assert not line2_camera_root.exists(), "Camera run directory exists; stop"
with zipfile.ZipFile(line2_camera_archive) as z:
    assert all(not Path(n).is_absolute() and '..' not in Path(n).parts for n in z.namelist())
    line2_camera_root.mkdir();z.extractall(line2_camera_root)
line2_camera_spec=importlib.util.spec_from_file_location('line2_camera_entry_b3ab3d3be1e24ee9b69cf676f3ec4326',line2_camera_root/'prepare_camera.py')
line2_camera_entry=importlib.util.module_from_spec(line2_camera_spec);line2_camera_spec.loader.exec_module(line2_camera_entry)
camera3_bundle,camera3_service_instance=line2_camera_entry.run(line2_camera_root,line2_fresh_initialized)
